// 场景：音乐源官方 favicon 本地打包（PNG base64），避免远程 Google s2 失败成色块。
// 源文件见 src/assets/provider-icons/*.png；勿再走网络拉图标。
import type { ImageSourcePropType } from "react-native";

function pngDataUri(b64: string): ImageSourcePropType {
  return { uri: `data:image/png;base64,${b64}` };
}

